		metadata.put("stringValue", "hello");
		metadata.put("integerValue", 123);
		metadata.put("doubleValue", 45.67);
		metadata.put("booleanValue", false);

		List<String> listValue = new ArrayList<>();
		listValue.add("item1");
		listValue.add("item2");
		metadata.put("listValue", listValue);

		EvaluationResponse response = new EvaluationResponse(true, 1.0f, "Mixed types test", metadata);

		// Act
		Map<String, Object> result = response.getMetadata();

		// Assert
		assertNotNull(result);
		assertEquals(5, result.size());

		assertTrue(result.get("stringValue") instanceof String);
		assertEquals("hello", result.get("stringValue"));

		assertTrue(result.get("integerValue") instanceof Integer);
		assertEquals(123, result.get("integerValue"));

		assertTrue(result.get("doubleValue") instanceof Double);
		assertEquals(45.67, result.get("doubleValue"));

		assertTrue(result.get("booleanValue") instanceof Boolean);
		assertEquals(false, result.get("booleanValue"));

		assertTrue(result.get("listValue") instanceof List);
		@SuppressWarnings("unchecked")
		List<String> retrievedList = (List<String>) result.get("listValue");
		assertEquals(2, retrievedList.size());
		assertEquals("item1", retrievedList.get(0));
		assertEquals("item2", retrievedList.get(1));
